// FLUENT 90 — content bank.
// 30 themes = 30 episodes of "Sam's Big Pitch" (a founder from Douala who takes his app to London),
// each with 10 chunks (natural phrases), 3 listening questions and a writing prompt.
// Questions: [question, correct answer, wrong, wrong] (shuffled on screen).
window.F90 = {};
F90.themes = [
{ t: 'Introductions', w: 'Introduce yourself: your name, your city and what you do.',
  c: [['Nice to meet you.', 'Enchanté(e).'], ["I'm from Cameroon.", 'Je viens du Cameroun.'], ['I live in Douala.', "J'habite à Douala."], ['I work in tech.', 'Je travaille dans la tech.'], ['What do you do?', 'Tu fais quoi dans la vie ?'], ["I'm into apps and business.", 'Je suis à fond dans les applis et le business.'], ['How about you?', 'Et toi ?'], ['My English is getting better.', "Mon anglais s'améliore."], ['Call me Sam.', 'Appelle-moi Sam.'], ["It's a pleasure.", 'Tout le plaisir est pour moi.']],
  s: { t: "Hi, I'm Sam", x: "Hi! My name is Samuel, but please call me Sam. I'm twenty-six, and I'm from Cameroon. I live in Douala, a big city by the sea. I work in tech. I'm building an app called PayLink. It helps small shops send bills and get paid by mobile money. My English is not perfect, but it's getting better every day. Why do I want to speak English? Because I want clients all over the world. Last night, I got an email from London. A tech summit wants me to come and present my app. I'm excited, and a little scared. Nice to meet you. This is my story.",
  q: [['Where does Sam live?', 'In Douala', 'In London', 'In Paris'], ['What does PayLink help shops do?', 'Get paid', 'Find workers', 'Sell phones'], ['Why is Sam excited?', 'A summit in London invited him', 'He bought a car', 'He finished school']] } },
{ t: 'Small talk', w: 'Write a short small-talk dialogue with a neighbour (4 lines).',
  c: [["How's it going?", 'Comment ça va ?'], ['Not bad, thanks.', 'Pas mal, merci.'], ["It's so hot today!", 'Il fait tellement chaud aujourd’hui !'], ['How was your weekend?', "C'était comment ton week-end ?"], ['Pretty busy, to be honest.', 'Assez chargé, pour être honnête.'], ['Same here.', 'Pareil pour moi.'], ['Are you from around here?', "Tu es d'ici ?"], ['What a day!', 'Quelle journée !'], ['Good to see you again.', 'Content de te revoir.'], ['Catch you later!', 'À plus tard !']],
  s: { t: 'Small talk with Grace', x: "Every morning, Sam buys bread from the same shop. Today, the owner, Grace, is there. Grace lived in Ghana for ten years, so she speaks English very well. \"How's it going, Sam?\" she asks. \"Not bad, thanks,\" Sam says. \"It's so hot today!\" Grace laughs. \"It's always hot in Douala! How was your weekend?\" \"Pretty busy, to be honest. I worked on my app.\" \"Same here. My shop was full of people.\" Sam has an idea. \"Grace, can we speak English every morning? Just five minutes.\" \"Good idea,\" she says. \"Catch you later, Sam!\"",
  q: [['Why does Grace speak English well?', 'She lived in Ghana', 'She studied in London', 'She watches movies'], ['What did Sam do at the weekend?', 'He worked on his app', 'He went to the beach', 'He slept all day'], ["What is Sam's idea?", 'Speak English with Grace every morning', 'Open a new shop', 'Move to Ghana']] } },
{ t: 'Talking about work', w: 'What do you do? Describe your work or your project.',
  c: [['I run a small business.', 'Je dirige une petite entreprise.'], ["I'm building an app.", 'Je développe une appli.'], ['It helps shops get paid faster.', 'Ça aide les boutiques à être payées plus vite.'], ['I work for myself.', 'Je travaille à mon compte.'], ['We have about fifty clients.', 'On a une cinquantaine de clients.'], ["It's still early days.", "C'est encore le début."], ["I'm in charge of sales.", "Je m'occupe des ventes."], ['Business is growing.', 'Les affaires se développent.'], ["I'm looking for new clients.", 'Je cherche de nouveaux clients.'], ["That's what I do.", "C'est ce que je fais."]],
  s: { t: 'What do you do?', x: "The next morning, Grace asks Sam a question. \"So, what do you do exactly?\" Sam takes a breath. \"I run a small business. I'm building an app called PayLink.\" \"What does it do?\" \"It helps shops get paid faster. Shop owners send a bill by SMS, and customers pay with mobile money.\" \"Interesting! Do you have clients?\" \"We have about fifty clients in Douala. It's still early days.\" \"Do you work alone?\" \"Yes, I work for myself. I'm in charge of everything: code, sales, support!\" Grace smiles. \"Is business growing?\" \"Slowly. I'm looking for new clients, maybe in other countries.\"",
  q: [['How do customers pay with PayLink?', 'With mobile money', 'With cash only', 'With a credit card'], ['How many clients does Sam have?', 'About fifty', 'About five hundred', 'Only one'], ['Who does the code and the sales?', 'Sam alone', 'Grace', 'A big team']] } },
{ t: 'Daily routine', w: 'Describe your typical day, from morning to night.',
  c: [['I usually wake up at six.', "Je me réveille d'habitude à six heures."], ['First thing in the morning, I check my phone.', 'Dès le matin, je regarde mon téléphone.'], ["I'm on my way.", 'Je suis en route.'], ['I grab a coffee.', 'Je prends un café (vite fait).'], ['I spend most of my day on my laptop.', 'Je passe la plupart de ma journée sur mon ordi.'], ['I take a short break.', 'Je fais une petite pause.'], ["I'm free after five.", 'Je suis libre après cinq heures.'], ['I go to bed late.', 'Je me couche tard.'], ['Every now and then', 'De temps en temps'], ['It depends on the day.', 'Ça dépend du jour.']],
  s: { t: "A day in Sam's life", x: "Sam usually wakes up at six. First thing in the morning, he checks his phone: messages from clients, emails, and news about tech. Then he grabs a coffee and walks to Grace's shop for his English practice. After that, he spends most of his day on his laptop. He writes code, answers clients and fixes small bugs. At one o'clock, he takes a short break and eats rice and fish. In the afternoon, he visits shops to sell PayLink. He's free after six, but he often works at night too. He goes to bed late. Every now and then, he watches English videos before he sleeps.",
  q: [['What does Sam do first in the morning?', 'He checks his phone', 'He goes running', 'He cooks breakfast'], ['What does Sam do in the afternoon?', 'He visits shops to sell PayLink', 'He sleeps', 'He goes to school'], ['When does Sam watch English videos?', 'Before he sleeps', 'At lunch', 'At six in the morning']] } },
{ t: 'Asking for clarification', w: "Write 3 sentences you can use when you don't understand someone.",
  c: [["Sorry, I didn't catch that.", "Désolé, je n'ai pas compris."], ['Could you say that again?', 'Tu peux répéter ?'], ['Could you speak a bit slower?', 'Tu peux parler un peu plus lentement ?'], ['What do you mean by that?', "Qu'est-ce que tu veux dire par là ?"], ['How do you spell that?', 'Ça s’écrit comment ?'], ['Let me make sure I understand.', "Laisse-moi vérifier que j'ai bien compris."], ["So you're saying that...", 'Donc tu dis que...'], ["I'm not sure I follow.", 'Je ne suis pas sûr de suivre.'], ["What's the word for...?", "C'est quoi le mot pour... ?"], ['Got it, thanks.', 'Compris, merci.']],
  s: { t: 'The first call', x: "On Tuesday, Sam gets a video call from London. A woman named Emma works for the Tech Bridge Summit. She speaks very fast. Sam feels nervous. \"Sorry, I didn't catch that,\" he says. \"Could you speak a bit slower?\" \"Of course!\" Emma says, slowly this time. \"We want you to give a five-minute pitch on stage.\" \"A pitch? What do you mean by that?\" \"A short presentation about your app, to sell your idea.\" \"Got it, thanks,\" Sam says. \"Let me make sure I understand: five minutes, on stage, in English?\" \"Exactly!\" Sam smiles, but his heart is beating fast.",
  q: [['Who is Emma?', 'She works for the Tech Bridge Summit', "She is Sam's sister", 'She is a shop owner'], ['What does Emma want?', 'A five-minute pitch on stage', 'A new phone', 'A free app'], ['How does Sam feel?', 'Nervous', 'Bored', 'Angry']] } },
{ t: 'Phone and video calls', w: 'Write a short message to start a video call with a client.',
  c: [['Can you hear me?', "Tu m'entends ?"], ["You're breaking up.", 'Ça coupe.'], ['My connection is bad.', 'Ma connexion est mauvaise.'], ['Let me share my screen.', 'Je partage mon écran.'], ["You're on mute.", 'Ton micro est coupé.'], ["I'll call you back.", 'Je te rappelle.'], ['Is now a good time?', "C'est un bon moment ?"], ['Thanks for your time.', 'Merci pour ton temps.'], ['Talk soon!', 'À bientôt !'], ["Let's hop on a call.", "On s'appelle vite fait."]],
  s: { t: 'Can you hear me?', x: "Two days later, Emma calls again. \"Hi Sam, can you hear me?\" \"Yes, but you're breaking up. My connection is bad today.\" Sam moves next to the window. \"Is that better?\" \"Much better! Is now a good time?\" \"Yes, perfect.\" \"Great. Let me share my screen.\" Emma shows him the summit program. There are two hundred investors and companies. \"Sam? Sam? I think you're on mute.\" Sam laughs and turns on his microphone. \"Sorry! This looks amazing.\" \"We'll send you the details by email. Thanks for your time!\" \"Thank you, Emma. Talk soon!\"",
  q: [['What problem does Sam have?', 'A bad connection', 'No laptop', "He's sick"], ['What does Emma share?', 'The summit program', 'A funny video', 'A photo'], ['How many investors and companies will be there?', 'Two hundred', 'Twenty', 'Two thousand']] } },
{ t: 'Money and prices', w: 'What is something you bought recently? Was it worth it?',
  c: [['How much is it?', 'Combien ça coûte ?'], ['It costs ten dollars a month.', 'Ça coûte dix dollars par mois.'], ["That's a bit expensive.", "C'est un peu cher."], ['Is there a discount?', 'Il y a une réduction ?'], ['Can I pay by mobile money?', 'Je peux payer par mobile money ?'], ["It's worth it.", 'Ça vaut le coup.'], ['We charge per shop.', 'On facture par boutique.'], ['Payment is due on Friday.', 'Le paiement est dû vendredi.'], ["I'll send you the invoice.", "Je t'envoie la facture."], ["It's within my budget.", "C'est dans mon budget."]],
  s: { t: 'How much is it?', x: "Sam needs money for the trip. The flight costs about eight hundred dollars. \"That's a bit expensive,\" he thinks. He looks at his business. Each shop pays ten dollars a month for PayLink. \"We charge per shop, not per user,\" he explains to Grace. \"Maybe I can raise the price?\" Grace thinks. \"Is PayLink worth it for shops?\" \"Yes! They get paid faster, and they save time.\" \"Then offer a premium plan. Fifteen dollars, with extra features.\" Sam likes the idea. That evening, he sends a message to all his clients. Twelve shops sign up for the premium plan. \"Now it's within my budget!\"",
  q: [['How much is the flight?', 'About eight hundred dollars', 'About eighty dollars', 'About eight thousand dollars'], ['What does Grace suggest?', 'A premium plan', 'A loan from the bank', 'Selling his laptop'], ['How many shops sign up?', 'Twelve', 'Fifty', 'Two']] } },
{ t: 'Giving your opinion', w: 'Give your opinion: is it important to speak English in business? Why?',
  c: [['I think that...', 'Je pense que...'], ['The way I see it, ...', 'De mon point de vue...'], ['In my experience, ...', "D'après mon expérience..."], ['To be honest, ...', 'Pour être honnête...'], ['It makes sense.', 'Ça a du sens.'], ["I'm not so sure about that.", "Je n'en suis pas si sûr."], ['It really depends on...', 'Ça dépend vraiment de...'], ['The main reason is...', "La raison principale, c'est..."], ['If you ask me, ...', 'Si tu veux mon avis...'], ['At the end of the day, ...', 'Au final...']],
  s: { t: 'What do you think?', x: "Sam's cousin Eric thinks the trip is a bad idea. \"London is far and expensive. Why go?\" Sam answers calmly. \"The way I see it, it's a big chance. The main reason is simple: I need clients outside Cameroon.\" \"But your English isn't great.\" \"To be honest, you're right. But it's getting better. In my experience, people care more about your idea than your accent.\" Eric is not convinced. \"I'm not so sure about that.\" \"It really depends on the person,\" Sam says. \"If you ask me, it's worth trying. At the end of the day, if I don't go, nothing changes.\"",
  q: [['What does Eric think?', 'The trip is a bad idea', 'The trip is perfect', 'Sam should go to Paris'], ['Why does Sam want to go?', 'He needs clients outside Cameroon', 'He wants a holiday', 'He wants to study'], ['According to Sam, what do people care about more?', 'Your idea', 'Your accent', 'Your clothes']] } },
{ t: 'Agreeing and disagreeing', w: "Someone says: 'Phones are bad for kids.' Agree or disagree, and explain why.",
  c: [['Exactly!', 'Exactement !'], ['I totally agree.', "Je suis tout à fait d'accord."], ['You have a point.', "Tu n'as pas tort."], ['I see what you mean, but...', 'Je vois ce que tu veux dire, mais...'], ["I'm not sure I agree.", "Je ne suis pas sûr d'être d'accord."], ["That's a good point.", "C'est un bon argument."], ['Fair enough.', 'Ok, ça se tient.'], ["Let's agree to disagree.", 'Restons sur nos positions.'], ['Sounds good to me.', 'Ça me va.'], ["We're on the same page.", 'On est sur la même longueur d’onde.']],
  s: { t: 'Fair enough', x: "Sam meets his friend Nadia, a designer. She looks at his pitch slides. \"Your slides have too much text,\" she says. \"You have a point,\" Sam says. \"But I need the text to remember what to say.\" \"I see what you mean, but people will read instead of listening to you.\" \"Fair enough. What do you suggest?\" \"One idea per slide. Big pictures, few words.\" \"That's a good point. And the colors?\" \"Use the PayLink green.\" \"Sounds good to me!\" They work for three hours. In the end, the slides look clean and simple. \"Now I just need to practice,\" Sam says. \"Exactly!\" Nadia replies.",
  q: [["What's the problem with the slides?", 'Too much text', 'Too many colors', 'They are too short'], ['What does Nadia suggest?', 'One idea per slide', 'More text', 'No slides at all'], ['How long do they work?', 'Three hours', 'Three days', 'Thirty minutes']] } },
{ t: 'Telling a story', w: 'Tell a short story about a hard moment and what happened in the end.',
  c: [['Last week, ...', 'La semaine dernière...'], ['It happened when...', "C'est arrivé quand..."], ['At first, I was nervous.', "Au début, j'étais stressé."], ['Then something weird happened.', "Puis il s'est passé un truc bizarre."], ["I couldn't believe it.", "Je n'en revenais pas."], ['In the end, ...', 'Finalement...'], ['It turned out that...', "Il s'est avéré que..."], ["I'll never forget it.", 'Je ne l’oublierai jamais.'], ['Long story short, ...', 'Pour faire court...'], ['It was a big lesson.', 'Ça a été une grosse leçon.']],
  s: { t: 'The day I almost quit', x: "That night, Sam tells Grace a story. \"Last year, I almost quit PayLink. It happened when my biggest client left. At first, I was really sad. I thought, maybe this isn't for me. Then something weird happened. The same week, three new shops called me. They heard about PayLink from a market seller. I couldn't believe it! It turned out that my old client was telling everyone about the app. Long story short, I got more clients than before. It was a big lesson: never give up too fast. I'll never forget it.\" Grace nods. \"That's why I'm going to London,\" Sam says.",
  q: [['Why did Sam almost quit?', 'His biggest client left', 'He was sick', 'He lost his phone'], ['How did the new shops hear about PayLink?', 'From a market seller', 'From TV', 'From a website'], ['What lesson did Sam learn?', 'Never give up too fast', 'Always work alone', "Don't trust clients"]] } },
{ t: 'Problems and solutions', w: 'Describe a problem you had this week and how you fixed it.',
  c: [['We have an issue.', 'On a un problème.'], ['The app keeps crashing.', "L'appli plante sans arrêt."], ["I'm working on it.", "Je m'en occupe."], ['Let me look into it.', 'Je vais regarder ça.'], ['What went wrong?', "Qu'est-ce qui n'a pas marché ?"], ["It's fixed now.", "C'est réparé maintenant."], ['Sorry for the trouble.', 'Désolé pour le dérangement.'], ["Let's figure it out.", 'Trouvons une solution.'], ["It's not a big deal.", "Ce n'est pas grave."], ['Thanks for your patience.', 'Merci pour ta patience.']],
  s: { t: 'The app keeps crashing', x: "One week before the trip, Sam's phone rings at midnight. It's Mrs. Bella, a client. \"Sam, we have an issue. The app keeps crashing!\" \"Sorry for the trouble. Let me look into it.\" Sam opens his laptop. What went wrong? He finds the problem: a new update has a small bug. He works until three in the morning. Finally, he sends a message: \"It's fixed now. Thanks for your patience.\" The next morning, Mrs. Bella calls again. \"It's not a big deal, Sam. You fixed it fast. That's why I trust you.\" Sam feels tired, but proud.",
  q: [['What is the problem?', 'The app keeps crashing', "The client didn't pay", 'The shop is closed'], ['What causes the problem?', 'A bug in a new update', 'A broken phone', 'No internet'], ['How does Mrs. Bella feel the next morning?', 'She trusts Sam', 'She is angry', 'She wants her money back']] } },
{ t: 'Plans and goals', w: 'What are your plans for the next 3 months?',
  c: [["I'm going to...", 'Je vais...'], ["I'm planning to travel.", 'Je compte voyager.'], ['Next month, ...', 'Le mois prochain...'], ['I hope to find investors.', "J'espère trouver des investisseurs."], ['My goal is to...', "Mon objectif, c'est de..."], ['If everything goes well, ...', 'Si tout se passe bien...'], ["I can't wait!", "J'ai trop hâte !"], ["We'll see.", 'On verra.'], ["I'm thinking about...", 'Je réfléchis à...'], ["It's on my to-do list.", "C'est sur ma liste."]],
  s: { t: 'The plan', x: "Sam writes his plan in a notebook. \"Next month, I'm going to fly to London. My goal is to find five international clients. I'm also planning to meet investors. I hope to find someone who believes in PayLink. If everything goes well, I'm going to hire two developers in Douala.\" He shows the plan to Grace. \"And your English?\" she asks. \"I'm thinking about practicing every day, three times a day. Morning, noon and night.\" \"Do you think you'll be ready?\" \"We'll see,\" Sam says. \"But it's on my to-do list, number one. I can't wait!\"",
  q: [["What is Sam's goal?", 'Find five international clients', 'Buy a house', 'Learn French'], ['What will Sam do if everything goes well?', 'Hire two developers', 'Move to London', 'Close PayLink'], ['How often does Sam plan to practice English?', 'Three times a day', 'Once a week', 'Once a month']] } },
{ t: 'Booking travel', w: 'Write a message to book a flight to a city you want to visit.',
  c: [["I'd like to book a flight.", 'Je voudrais réserver un vol.'], ['A one-way ticket', 'Un aller simple'], ['A round-trip ticket', 'Un aller-retour'], ['Is it a direct flight?', "C'est un vol direct ?"], ['What time does it leave?', 'Il part à quelle heure ?'], ['I have a layover in Paris.', "J'ai une escale à Paris."], ['Can I change the date?', 'Je peux changer la date ?'], ['I need a visa.', "J'ai besoin d'un visa."], ['Window or aisle?', 'Hublot ou couloir ?'], ["I'll book it online.", 'Je vais réserver en ligne.']],
  s: { t: 'Booking the flight', x: "Sam calls a travel agency. \"Hello, I'd like to book a flight from Douala to London.\" \"One-way or round-trip?\" \"A round-trip ticket, please.\" \"There's no direct flight. You'll have a layover in Paris.\" \"What time does it leave?\" \"At eleven p.m. on the fourteenth.\" \"Can I change the date if I need to?\" \"Yes, for a small fee. Window or aisle?\" \"Window, please. I want to see the clouds!\" The agent laughs. \"And remember, you need a visa for the UK.\" \"Yes, I already have it.\" \"Perfect. I'll send the ticket by email.\" \"Thank you so much!\"",
  q: [["Where is Sam's layover?", 'In Paris', 'In Lagos', 'In Dubai'], ['What seat does Sam choose?', 'Window', 'Aisle', 'Middle'], ['What does Sam need for the UK?', 'A visa', 'A car', 'A new phone']] } },
{ t: 'At the airport', w: "You're at immigration. Answer: why are you here, and how long are you staying?",
  c: [['Where do I check in?', "Où est l'enregistrement ?"], ["Here's my passport.", 'Voici mon passeport.'], ['I only have carry-on.', "J'ai seulement un bagage cabine."], ['Which gate is it?', "C'est quelle porte ?"], ['My flight is delayed.', 'Mon vol est retardé.'], ['I missed my connection.', "J'ai raté ma correspondance."], ["What's the purpose of your visit?", 'Quel est le but de votre visite ?'], ["I'm here for a conference.", 'Je suis ici pour une conférence.'], ["Where's baggage claim?", 'Où récupère-t-on les bagages ?'], ["I'm staying for five days.", 'Je reste cinq jours.']],
  s: { t: 'At the airport', x: "At Douala airport, Sam is nervous. \"Where do I check in for Paris?\" A guard points to counter four. \"Here's my passport,\" he says. \"Any bags?\" \"No, I only have carry-on.\" After a long night, he lands in Paris. But there's bad news: his flight to London is delayed by three hours. \"Did I miss my connection?\" he asks. \"No, sir, your next flight is also late.\" Finally, he arrives in London. The officer asks, \"What's the purpose of your visit?\" \"I'm here for a conference. I'm staying for five days.\" \"Welcome to London.\" Sam smiles. He did it.",
  q: [['What luggage does Sam have?', 'Only carry-on', 'Three big bags', 'No luggage and no passport'], ['What happens in Paris?', 'His flight is delayed', 'He loses his bag', 'He meets Emma'], ['How long is Sam staying in London?', 'Five days', 'Five weeks', 'One day']] } },
{ t: 'At the hotel', w: 'Write a message to a hotel: you have a problem in your room.',
  c: [['I have a reservation.', "J'ai une réservation."], ['Under the name Ndongo.', 'Au nom de Ndongo.'], ['What time is checkout?', "Le départ, c'est à quelle heure ?"], ['Is breakfast included?', 'Le petit-déjeuner est compris ?'], ["What's the Wi-Fi password?", "C'est quoi le mot de passe Wi-Fi ?"], ["The heater isn't working.", 'Le chauffage ne marche pas.'], ['Could I get an extra blanket?', 'Je pourrais avoir une couverture en plus ?'], ['Can I leave my bag here?', 'Je peux laisser mon sac ici ?'], ['Could you call me a taxi?', "Vous pouvez m'appeler un taxi ?"], ['Everything is perfect, thanks.', 'Tout est parfait, merci.']],
  s: { t: 'The hotel', x: "Sam takes a taxi to his hotel. \"Hi, I have a reservation under the name Ndongo.\" \"Welcome! You're in room 412. Breakfast is included, from seven to ten.\" \"What time is checkout?\" \"Eleven a.m. on Friday.\" \"And what's the Wi-Fi password?\" \"It's on your key card.\" In the room, Sam sees a problem: the heater isn't working, and London is cold! He calls the front desk. \"The heater isn't working. Could I also get an extra blanket?\" Ten minutes later, a man fixes it. \"Everything is perfect, thanks!\" Sam says. He sleeps for ten hours.",
  q: [['Is breakfast included?', 'Yes, from seven to ten', 'No, never', 'Only on Friday'], ["What's the problem in the room?", "The heater isn't working", 'The TV is broken', "There's no bed"], ['Where is the Wi-Fi password?', 'On the key card', 'On the door', 'In the bathroom']] } },
{ t: 'Getting around', w: 'Explain how to go from your home to your favorite place.',
  c: [['How do I get to the station?', 'Comment je vais à la gare ?'], ['Is it far from here?', "C'est loin d'ici ?"], ["It's a ten-minute walk.", "C'est à dix minutes à pied."], ['Take the second left.', 'Prends la deuxième à gauche.'], ['Which line goes there?', 'Quelle ligne va là-bas ?'], ["I think I'm lost.", 'Je crois que je suis perdu.'], ['Can you show me on the map?', 'Tu peux me montrer sur la carte ?'], ['Keep going straight.', 'Continue tout droit.'], ["It's just around the corner.", "C'est juste au coin."], ["Thanks, you're a lifesaver!", 'Merci, tu me sauves la vie !']],
  s: { t: 'Lost in London', x: "The next day, Sam wants to visit the summit venue. He takes the Underground, but he gets off at the wrong station. \"I think I'm lost,\" he says to a woman. \"How do I get to the ExCeL Centre?\" \"Oh, it's not far from here. Take the DLR train. The station is just around the corner.\" \"Can you show me on the map?\" She points at his phone. \"Keep going straight, then take the second left. It's a ten-minute walk.\" \"Thanks, you're a lifesaver!\" Twenty minutes later, Sam stands in front of the huge building. Tomorrow, he will be on stage here.",
  q: [['What mistake does Sam make?', 'He gets off at the wrong station', 'He loses his passport', 'He misses the summit'], ['How far is the station?', 'A ten-minute walk', 'One hour by car', 'Very far'], ['Where will Sam be tomorrow?', 'On stage in that building', 'At the airport', 'In Paris']] } },
{ t: 'At the restaurant', w: 'Describe your favorite meal and where you eat it.',
  c: [['A table for two, please.', 'Une table pour deux, s’il vous plaît.'], ['What do you recommend?', "Qu'est-ce que vous recommandez ?"], ["I'll have the chicken.", 'Je vais prendre le poulet.'], ['Can I see the menu?', 'Je peux voir la carte ?'], ['Not too spicy, please.', 'Pas trop épicé, s’il vous plaît.'], ['This is delicious!', "C'est délicieux !"], ['Could we get the bill?', "On pourrait avoir l'addition ?"], ["Let's split it.", 'On partage.'], ["It's on me.", "C'est pour moi, je t'invite."], ['Keep the change.', 'Gardez la monnaie.']],
  s: { t: 'Dinner with new friends', x: "In the evening, Emma invites Sam to dinner with two other speakers: Kenji from Japan and Lucia from Brazil. \"A table for four, please,\" Emma says. Sam looks at the menu. \"What do you recommend?\" he asks the waiter. \"The fish and chips is very popular.\" \"I'll have that, please.\" \"This is delicious!\" Lucia says. They talk about startups for two hours. Kenji explains his robot company, and Lucia talks about her food delivery app. At the end, Sam says, \"Could we get the bill?\" Kenji says, \"Let's split it.\" But Emma smiles: \"No, it's on me. Welcome to London!\"",
  q: [['Where is Kenji from?', 'Japan', 'Brazil', 'Ghana'], ['What does Sam order?', 'Fish and chips', 'Chicken', 'Pizza'], ['Who pays the bill?', 'Emma', 'Sam', 'Kenji']] } },
{ t: 'Networking', w: 'You meet someone at a tech event. Write what you say in the first minute.',
  c: [['What brings you here?', "Qu'est-ce qui t'amène ici ?"], ['What are you working on?', 'Tu travailles sur quoi ?'], ['That sounds interesting!', "Ça a l'air intéressant !"], ['How did you get into tech?', "Comment tu t'es lancé dans la tech ?"], ["Let's stay in touch.", 'Restons en contact.'], ['Are you on LinkedIn?', 'Tu es sur LinkedIn ?'], ["Here's my card.", 'Voici ma carte.'], ["I'd love to hear more.", "J'aimerais bien en savoir plus."], ['It was great talking to you.', "C'était super de discuter avec toi."], ['Let me introduce you to Priya.', 'Laisse-moi te présenter Priya.']],
  s: { t: 'Networking', x: "Day one of the summit. The hall is full of people. Sam takes a deep breath and walks to a man near the coffee. \"Hi, I'm Sam. What brings you here?\" \"I'm Daniel. I run a payment company in Kenya. What are you working on?\" Sam explains PayLink. \"That sounds interesting! How did you get into tech?\" \"I taught myself to code on YouTube.\" \"Wow. I'd love to hear more. Are you on LinkedIn?\" \"Yes! Here's my card.\" Later, Daniel says, \"Let me introduce you to Priya. She owns forty shops in the UK.\" Sam can't believe his luck. \"It was great talking to you, Daniel!\"",
  q: [["Where is Daniel's company?", 'In Kenya', 'In the UK', 'In Cameroon'], ['How did Sam learn to code?', 'On YouTube', 'At university', 'From his father'], ['Who is Priya?', 'She owns forty shops in the UK', 'She is a teacher', 'She works at the hotel']] } },
{ t: 'Pitching your product', w: 'Write a 4-sentence pitch for your project or business.',
  c: [['We help small shops get paid.', 'On aide les petites boutiques à être payées.'], ['The problem is that...', "Le problème, c'est que..."], ['Our solution is simple.', 'Notre solution est simple.'], ["Here's how it works.", 'Voici comment ça marche.'], ['We already have paying customers.', 'On a déjà des clients qui paient.'], ["We're growing twenty percent a month.", 'On croît de vingt pour cent par mois.'], ['What makes us different is...', "Ce qui nous rend différents, c'est..."], ["We're looking for partners.", 'On cherche des partenaires.'], ['Does that make sense?', 'Est-ce que c’est clair ?'], ['Any questions?', 'Des questions ?']],
  s: { t: 'The pitch', x: "It's time. Sam walks on stage. Two hundred people look at him. \"Hello everyone. We help small shops get paid. The problem is that many shop owners lose money because customers pay late. Our solution is simple: PayLink. Here's how it works: you send a bill by SMS, and the customer pays with one click. We already have sixty-two paying customers, and we're growing twenty percent a month. What makes us different is that it works with mobile money, on any phone. We're looking for partners in Africa and the UK. Does that make sense? Thank you! Any questions?\" The room applauds.",
  q: [['What problem does PayLink solve?', 'Customers pay late', 'Shops have no electricity', 'Phones are too expensive'], ['How many paying customers does Sam have now?', 'Sixty-two', 'Twenty', 'Two hundred'], ['What makes PayLink different?', 'It works with mobile money on any phone', "It's free forever", "It's only for big companies"]] } },
{ t: 'Explaining tech simply', w: 'Explain an app you love to someone who has never used it.',
  c: [["Basically, it's an app that...", "En gros, c'est une appli qui..."], ['Think of it like...', 'Imagine ça comme...'], ['In simple terms, ...', 'En termes simples...'], ['It runs in the cloud.', 'Ça tourne dans le cloud.'], ['You just sign up and...', "Tu t'inscris, et c'est tout..."], ['It syncs across devices.', 'Ça se synchronise entre les appareils.'], ['It works offline too.', 'Ça marche aussi hors ligne.'], ['The data is secure.', 'Les données sont sécurisées.'], ['Let me show you a demo.', 'Laisse-moi te montrer une démo.'], ["It's easier than it sounds.", "C'est plus simple qu'il n'y paraît."]],
  s: { t: 'Explain it simply', x: "After the pitch, a journalist asks Sam, \"Can you explain PayLink to my readers? They're not tech people.\" \"Of course. Basically, it's an app that sends bills. Think of it like a WhatsApp message that asks for money, but very polite!\" She laughs. \"In simple terms, the shop owner just signs up, adds a customer, and clicks send. It runs in the cloud, so it syncs across devices: phone, tablet or laptop. And it works offline too: the bill leaves when the internet comes back.\" \"Is the data safe?\" \"Yes, the data is secure. Let me show you a demo. It's easier than it sounds.\"",
  q: [['Who asks Sam to explain PayLink?', 'A journalist', 'An investor', 'A shop owner'], ['What does Sam compare PayLink to?', 'A WhatsApp message', 'A bank', 'A taxi'], ["What happens when there's no internet?", 'The bill leaves when the internet comes back', 'The app deletes the bill', 'Nothing works']] } },
{ t: 'Talking about AI', w: 'How do you use AI in your life? Is it good or bad for you?',
  c: [['AI is changing everything.', "L'IA change tout."], ['It saves me hours every week.', 'Ça me fait gagner des heures chaque semaine.'], ['I use it to write code.', "Je l'utilise pour écrire du code."], ["It's not perfect, though.", "Ce n'est pas parfait, cela dit."], ['You still need to check its work.', 'Il faut quand même vérifier son travail.'], ["It's a tool, not a replacement.", "C'est un outil, pas un remplaçant."], ['Some people are worried about jobs.', "Certains s'inquiètent pour les emplois."], ['On the bright side, ...', "Le bon côté, c'est que..."], ["It's moving so fast.", 'Ça avance tellement vite.'], ["I'm curious to see what's next.", 'Je suis curieux de voir la suite.']],
  s: { t: 'The AI panel', x: "In the afternoon, Sam watches a panel about artificial intelligence. A speaker says, \"AI is changing everything. It saves me hours every week.\" Another speaker answers, \"It's not perfect, though. You still need to check its work.\" During questions, Sam raises his hand. \"I use AI to write code for PayLink. For me, it's a tool, not a replacement. Some people in Cameroon are worried about jobs, but on the bright side, a small team can now build big things.\" People nod. A woman in the front row turns around and smiles at him. It's Priya, the businesswoman with forty shops. \"Let's talk after this,\" she says.",
  q: [["According to the second speaker, what's the problem with AI?", 'You still need to check its work', "It's too expensive", "It's too slow"], ['How does Sam use AI?', 'To write code', 'To translate songs', 'To drive his car'], ['Who wants to talk to Sam after the panel?', 'Priya', 'Emma', 'Grace']] } },
{ t: 'Negotiating', w: 'A client wants a 30% discount. Write your answer.',
  c: [["What's your budget?", 'Quel est ton budget ?'], ['Can you do better on the price?', 'Tu peux faire mieux sur le prix ?'], ["That's our best offer.", "C'est notre meilleure offre."], ["Let's meet in the middle.", 'Coupons la poire en deux.'], ['What if we sign for a year?', 'Et si on signe pour un an ?'], ['I need to think about it.', 'Je dois y réfléchir.'], ['We can offer a free trial.', 'On peut proposer un essai gratuit.'], ['That works for us.', 'Ça nous va.'], ['Let me check with my team.', 'Je vérifie avec mon équipe.'], ['Do we have a deal?', 'Marché conclu ?']],
  s: { t: 'The negotiation', x: "Priya is direct. \"I like PayLink. I want to try it in my forty shops. What's the price?\" \"Fifteen dollars per shop, per month.\" \"That's six hundred a month. Can you do better on the price?\" Sam thinks fast. \"What's your budget?\" \"Four hundred.\" \"Hmm. Let's meet in the middle: five hundred, with a free trial for the first month.\" \"What if we sign for a year?\" \"Then four hundred and fifty, and that's our best offer.\" Priya smiles. \"I need to think about it. Let me check with my team.\" \"Of course.\" That night, Sam can't sleep. Do they have a deal?",
  q: [['How many shops does Priya have?', 'Forty', 'Fifteen', 'Four hundred'], ['What does Sam offer for the first month?', 'A free trial', 'Fifty percent off', 'A new phone'], ["What's the final price for a one-year contract?", 'Four hundred and fifty a month', 'Six hundred a month', 'Five hundred a month']] } },
{ t: 'Emails and messages', w: "Write a follow-up email to a client who didn't answer.",
  c: [["Hope you're doing well.", "J'espère que tu vas bien."], ['Just following up on our call.', 'Je reviens vers toi suite à notre appel.'], ['Please find attached...', 'Veuillez trouver ci-joint...'], ['Let me know if you have any questions.', 'Dis-moi si tu as des questions.'], ['Looking forward to hearing from you.', "Au plaisir d'avoir de tes nouvelles."], ['Sorry for the late reply.', 'Désolé pour la réponse tardive.'], ['As discussed, ...', 'Comme convenu...'], ['Quick question: ...', 'Petite question : ...'], ['Thanks in advance.', "Merci d'avance."], ['Best regards,', 'Cordialement,']],
  s: { t: 'Following up', x: "The next morning, Sam writes an email. \"Hi Priya, Hope you're doing well. Just following up on our conversation yesterday. As discussed, we can offer four hundred and fifty dollars a month for your forty shops, with a one-year contract. Please find attached a short presentation with prices and a demo link. Let me know if you have any questions. Looking forward to hearing from you. Best regards, Sam.\" He reads it three times, then clicks send. One hour later, he gets a reply: \"Sorry for the late reply, I was in a meeting. Quick question: can we have a video call tomorrow? Thanks in advance, Priya.\"",
  q: [['What does Sam attach to the email?', 'A short presentation', 'A photo of his family', 'A signed contract'], ['How many times does Sam read his email?', 'Three times', 'Once', 'Ten times'], ['What does Priya ask for?', 'A video call tomorrow', 'A cheaper price', 'A new app']] } },
{ t: 'Meetings', w: 'Write the opening of a meeting: welcome, goal, first point.',
  c: [["Let's get started.", 'Commençons.'], ['Thanks for joining.', "Merci d'être là."], ['The goal today is...', "L'objectif aujourd'hui, c'est..."], ['Can I add something?', 'Je peux ajouter quelque chose ?'], ["Let's move on.", 'Passons à la suite.'], ["Who's going to handle this?", "Qui s'en charge ?"], ["Let's come back to that later.", 'On y reviendra plus tard.'], ["We're running out of time.", 'On manque de temps.'], ['To sum up, ...', 'Pour résumer...'], ['The next steps are...', 'Les prochaines étapes sont...']],
  s: { t: 'The meeting', x: "The next day, Sam joins a video meeting with Priya and her team. \"Thanks for joining,\" Priya says. \"Let's get started. The goal today is to decide about PayLink.\" Her IT manager, Tom, asks many questions about security. Sam answers clearly. Then Tom says, \"Can I add something? We need training for our staff.\" \"No problem, I can do online training,\" Sam says. \"Great, let's move on. Who's going to handle support?\" \"Me, at first. Then my new team.\" \"We're running out of time,\" Priya says. \"To sum up: the price is fine, and training is included. The next steps are the contract and a start date.\"",
  q: [['What does Tom ask about?', 'Security', 'Lunch', 'The weather'], ["What does Priya's team need?", 'Training for their staff', 'New phones', 'A bigger office'], ['What are the next steps?', 'The contract and a start date', 'Another pitch', 'A trip to Douala']] } },
{ t: 'Reactions and feelings', w: 'Write how you react to: great news, bad news, and a surprise.',
  c: [['No way!', 'Pas possible !'], ["That's amazing!", "C'est incroyable !"], ["I'm so happy for you.", 'Je suis trop content pour toi.'], ["That's a shame.", "C'est dommage."], ['Oh, I see.', 'Ah, je vois.'], ['Really? Tell me more.', 'Vraiment ? Raconte.'], ["I'm so excited!", 'Je suis surexcité !'], ["That's a relief.", 'Ça me soulage.'], ["I'm a bit stressed.", 'Je suis un peu stressé.'], ['Good for you!', 'Bravo, tant mieux pour toi !']],
  s: { t: 'Good news', x: "Sam calls Grace in Douala. \"Grace, guess what? Priya said yes! Forty shops!\" \"No way! That's amazing! I'm so happy for you!\" \"I'm so excited, but I'm a bit stressed too. It's a big client.\" \"That's normal. Really, tell me more!\" Sam explains everything. Then Grace has bad news. \"The shop next to mine closed. The owner couldn't pay his bills.\" \"Oh, I see. That's a shame.\" \"But he wants to try PayLink when he opens again.\" \"That's a relief! Good for him.\" Sam hangs up and looks at London through the window. Everything is changing.",
  q: [["What's the good news?", 'Priya said yes', 'Sam won money', 'Grace is moving'], ['How does Sam feel?', 'Excited but a bit stressed', 'Sad', 'Bored'], ["What's Grace's bad news?", 'The shop next to hers closed', 'Her shop is on fire', 'She is sick']] } },
{ t: 'Apologies and complaints', w: 'A customer is angry. Write your apology and your solution.',
  c: [["I'm really sorry about that.", 'Je suis vraiment désolé pour ça.'], ["That's my fault.", "C'est ma faute."], ["It won't happen again.", 'Ça ne se reproduira pas.'], ['Let me make it right.', 'Laisse-moi arranger ça.'], ['I understand your frustration.', 'Je comprends ta frustration.'], ["Here's what we'll do.", "Voici ce qu'on va faire."], ["We'll refund you.", 'On va te rembourser.'], ["I'd like to make a complaint.", 'Je voudrais faire une réclamation.'], ["This isn't what I ordered.", "Ce n'est pas ce que j'ai commandé."], ['Thanks for letting us know.', 'Merci de nous avoir prévenus.']],
  s: { t: 'A mistake', x: "Back in Douala, the first week with Priya's shops goes badly. Some bills go to the wrong customers! A shop manager in Manchester writes: \"I'd like to make a complaint. This isn't what we ordered. Our customers are confused.\" Sam calls him immediately. \"I'm really sorry about that. That's my fault: I made a mistake in the settings. I understand your frustration. Here's what we'll do: I'll fix it today, and we'll refund you this month.\" The manager calms down. \"Thanks for letting us know so fast.\" \"Let me make it right. It won't happen again.\" That night, Sam fixes everything.",
  q: [["What's the problem?", 'Bills go to the wrong customers', 'The app is too expensive', 'The shop is closed'], ['Where is the angry manager?', 'In Manchester', 'In Douala', 'In Paris'], ['What will Sam do?', 'Fix it and refund this month', 'Close PayLink', 'Ignore it']] } },
{ t: 'Closing a deal', w: 'Write a message to confirm a deal with a new client.',
  c: [["Let's make it happen.", 'Faisons-le.'], ["I'll send over the contract.", "Je t'envoie le contrat."], ['When can we start?', 'On peut commencer quand ?'], ["We're excited to work with you.", 'On a hâte de travailler avec vous.'], ["It's a win-win.", "C'est gagnant-gagnant."], ["Let's set a deadline.", 'Fixons une date limite.'], ["I'll keep you posted.", 'Je te tiens au courant.'], ['Deal!', 'Marché conclu !'], ['Welcome on board!', 'Bienvenue à bord !'], ["Let's celebrate!", 'Fêtons ça !']],
  s: { t: 'The deal', x: "After the problem is fixed, Priya calls. \"Sam, you handled that very well. We want to sign for two years, and add twenty more shops.\" Sam almost drops his phone. \"Deal! Let's make it happen. I'll send over the contract today.\" \"When can we start?\" \"On the first of next month. Let's set a deadline for the training: two weeks.\" \"Perfect. It's a win-win.\" \"We're excited to work with you, Priya. I'll keep you posted.\" \"Welcome on board, Sam!\" Sam calls his two new developers. \"Team, let's celebrate! Tonight, dinner is on me!\"",
  q: [['How many more shops does Priya add?', 'Twenty', 'Forty', 'Two'], ['How long is the new contract?', 'Two years', 'Two months', 'Ten years'], ['Who pays for dinner?', 'Sam', 'Priya', 'The developers']] } },
{ t: 'Social media', w: 'Write the caption of a video about your project.',
  c: [['Check out my new video.', 'Regarde ma nouvelle vidéo.'], ['Link in bio.', 'Lien dans la bio.'], ["Don't forget to subscribe.", "N'oubliez pas de vous abonner."], ['It went viral.', "C'est devenu viral."], ['Drop a comment below.', 'Laisse un commentaire en dessous.'], ['I post every Monday.', 'Je poste chaque lundi.'], ['Behind the scenes', 'Les coulisses'], ['Thanks for watching!', "Merci d'avoir regardé !"], ['Let me know what you think.', "Dis-moi ce que tu en penses."], ['Stay tuned!', 'Restez connectés !']],
  s: { t: 'Going viral', x: "Sam decides to share his story online. He records a video in English: \"From Douala to London: how I got my first international client.\" He's nervous, but he posts it. \"Check out my new video! Link in bio.\" The next morning, his phone is crazy. The video went viral: two hundred thousand views! People write comments from Nigeria, India and Canada. \"Thanks for watching, everyone!\" he writes. \"Drop a comment below: what are you building?\" He decides to post every Monday, behind the scenes of PayLink. \"Stay tuned!\" he says at the end of each video. His English is not perfect. Nobody cares.",
  q: [["What is Sam's video about?", 'How he got his first international client', 'How to cook fish', 'His holiday'], ['How many views does the video get?', 'Two hundred thousand', 'Two hundred', 'Two million'], ['When will Sam post videos?', 'Every Monday', 'Every day', 'Never again']] } },
{ t: 'Friends abroad', w: 'Invite a new friend to visit your city. What will you do together?',
  c: [['Do you want to hang out?', 'Tu veux qu’on se voie ?'], ['Are you free this weekend?', 'Tu es libre ce week-end ?'], ["Let's grab a drink.", 'Allons boire un verre.'], ["I'd love to!", 'Avec plaisir !'], ['Maybe another time.', 'Peut-être une autre fois.'], ["Text me when you're here.", 'Envoie-moi un message quand tu es là.'], ['Make yourself at home.', 'Fais comme chez toi.'], ['I had a great time.', "J'ai passé un super moment."], ['You should visit Cameroon!', 'Tu devrais visiter le Cameroun !'], ['Keep in touch!', 'Garde le contact !']],
  s: { t: 'Friends abroad', x: "Lucia, the Brazilian founder from the dinner, sends Sam a message. \"I'm coming to Africa for work next month. Are you free that weekend?\" \"Of course! You should visit Cameroon! Text me when you're here.\" A month later, Lucia arrives in Douala. \"Make yourself at home,\" Sam says. They visit the market, eat grilled fish by the sea, and meet Grace. \"Do you want to hang out tonight?\" Grace asks. \"Let's grab a drink at the beach.\" \"I'd love to!\" Lucia says. Before leaving, she hugs Sam. \"I had a great time. Keep in touch, and come to São Paulo next!\"",
  q: [['Why does Lucia come to Africa?', 'For work', 'For a wedding', 'To study'], ['What do they eat by the sea?', 'Grilled fish', 'Pizza', 'Burgers'], ['Where does Lucia invite Sam?', 'To São Paulo', 'To Tokyo', 'To London']] } },
{ t: 'Looking back', w: 'Look back at your month. What changed? What comes next?',
  c: [['Looking back, ...', 'Avec le recul...'], ["I've come a long way.", "J'ai fait beaucoup de chemin."], ['I used to be afraid of my accent.', "Avant, j'avais peur de mon accent."], ['Now I feel confident.', 'Maintenant, je me sens confiant.'], ['The hardest part was...', "Le plus dur, c'était..."], ['I learned that...', "J'ai appris que..."], ["I'm proud of myself.", 'Je suis fier de moi.'], ['It was worth it.', 'Ça en valait la peine.'], ['This is just the beginning.', "Ce n'est que le début."], ['Step by step.', 'Pas à pas.']],
  s: { t: 'Looking back', x: "Ninety days ago, Sam couldn't say three sentences in English without stopping. Today, he speaks to clients in London every week. \"Looking back, I've come a long way,\" he tells Grace. \"I used to be afraid of my accent. Now I feel confident. The hardest part was the first month: I wanted to quit every day. But I practiced in the morning, at noon and at night. I learned that you don't need perfect English. You need English that works.\" Grace smiles. \"Are you proud of yourself?\" \"Yes. It was worth it. And this is just the beginning. Step by step.\"",
  q: [['What was Sam afraid of?', 'His accent', 'Airplanes', 'Money'], ['When did Sam practice?', 'Morning, noon and night', 'Only at weekends', 'Once a month'], ['What did Sam learn?', 'You need English that works', 'You need perfect grammar', 'You must live abroad']] } }
];

// Reflex situations (no translation, answer fast): [situation, a natural answer]
F90.reflex = [
['A client says: "Your app crashed again."', "I'm really sorry about that. Let me look into it right now."],
['At a meetup, someone asks: "So, what do you do?"', "I run a small tech business. I'm building an app that helps shops get paid."],
["On a video call, the other person's audio cuts out.", "Sorry, you're breaking up. Could you say that again?"],
['The waiter brings you the wrong dish.', "Excuse me, I think this isn't what I ordered."],
["You arrive at your hotel at 9 a.m. Check-in is at 3 p.m.", "Hi, I'm a bit early. Can I leave my bag here?"],
['A client asks you for a discount.', "Let me see what I can do. What's your budget?"],
["You didn't understand a word in a meeting.", 'Sorry, what do you mean by that?'],
["A friend invites you out, but you're busy.", "I'd love to, but I'm busy tonight. Maybe another time?"],
["You're lost in a new city.", "Excuse me, I think I'm lost. How do I get to the station?"],
['Someone asks your opinion about AI.', 'The way I see it, AI is a great tool, but you still need to check its work.'],
["Your flight is delayed and you'll miss your connection.", 'My flight is delayed. Can you help me with my connection?'],
['A partner says: "Let\'s meet in the middle."', "Sounds good to me. Let's do it."],
['You need to end a call politely.', 'Thanks for your time. Talk soon!'],
['A new contact gives you their card.', "Thanks! Let's stay in touch. Are you on LinkedIn?"],
['A customer is angry about a late delivery.', "I understand your frustration. Here's what we'll do."],
['Someone speaks too fast for you.', 'Could you speak a bit slower, please?'],
['You want to know the price of a hotel room.', 'How much is it per night?'],
['A colleague shares great news.', "No way! That's amazing! I'm so happy for you."],
['You start a meeting.', "Thanks for joining. Let's get started."],
['You forgot the word "receipt".', 'Can I have the paper they give you after you pay?'],
['Immigration officer: "What\'s the purpose of your visit?"', "I'm here for a conference. I'm staying for five days."],
['A friend asks: "How was your weekend?"', 'Pretty busy, to be honest. How about you?'],
['You want to show your app on a call.', 'Let me share my screen and show you a quick demo.'],
['A client asks: "Is our data safe?"', 'Yes, the data is secure. Let me explain how.'],
['You need more time to decide.', 'I need to think about it. Can I get back to you tomorrow?'],
['Someone thanks you for your help.', 'No worries at all. Happy to help!'],
['You finished dinner and want to split the bill.', "Could we get the bill, please? Let's split it."],
["A client didn't answer your email.", 'Hi, just following up on my last email. Any news?'],
['In a meeting, you want to add an idea.', 'Can I add something? I think we could try a free trial.'],
['Someone asks where you are from.', "I'm from Cameroon. I live in Douala."],
['Your internet is bad during a call.', "Sorry, my connection is bad. I'll call you back."],
["A client wants a feature you don't have yet.", "That's a good point. It's on our to-do list."],
["Your hotel room is cold.", "Hi, the heater isn't working. Could someone check it?"],
['A stranger says they liked your presentation.', "Thank you so much! I'm glad you liked it."],
['You want to invite a new friend for coffee.', 'Do you want to grab a coffee this week?'],
['Someone disagrees with you.', "I see what you mean, but I think it depends on the market."],
['The client says yes to your offer.', "Deal! I'll send over the contract today."],
['A taxi driver asks: "Where to?"', 'To the city centre, please. How long does it take?'],
['Explain your app in one sentence.', "Basically, it's an app that helps shops get paid faster."],
['Someone asks why you are learning English.', 'Because I want clients all over the world.'],
['Your colleague is on mute and talking.', "Sorry, you're on mute. We can't hear you."],
['A shop says your price is too high.', "I understand. It's worth it because you get paid faster. Can I show you?"]
];

