// AI role-plays. p = first phase where it appears in the daily rotation.
F90.roleplays = [
{ id: 'coffee', p: 1, t: 'Coffee with a new friend', role: 'Alex, a friendly Londoner who works in a coworking café. Curious, relaxed, asks simple personal questions.', goal: 'Make a new friend: introduce yourself and ask questions back.', open: "Hey! Is this seat free? I'm Alex, by the way." },
{ id: 'client', p: 1, t: 'Video call with a client', role: 'Priya, owner of 40 shops in the UK. Busy, direct, interested in the app the learner sells. Asks what it does, the price and why it is better.', goal: 'Explain your app, its price and why it helps.', open: 'Hi! Thanks for taking the time. So, tell me about your app.' },
{ id: 'checkin', p: 1, t: 'Airport check-in', role: 'An airline agent at Paris Charles de Gaulle airport. Polite, efficient. Asks for passport, bags, seat preference. Then announces the flight is delayed.', goal: 'Check in for your flight to London and handle the delay.', open: 'Good evening. Where are you flying today?' },
{ id: 'hotel', p: 1, t: 'Hotel problem', role: 'A London hotel receptionist. The room is not ready yet and the learner arrived early. Offers solutions.', goal: 'Get a solution: leave your bag, ask questions, stay polite.', open: "Good morning, welcome to the Riverside Hotel! How can I help you?" },
{ id: 'network', p: 1, t: 'Networking at a summit', role: 'Daniel, founder of a payment company in Kenya, at a tech summit. Friendly, asks about the learner’s work and background.', goal: 'Present yourself and get his contact.', open: "Hi there! Great talk this morning, right? What brings you here?" },
{ id: 'waiter', p: 1, t: 'Ordering at a restaurant', role: 'A waiter in a busy London restaurant. Recommends dishes, asks about drinks, later brings the bill.', goal: 'Order food, ask for a recommendation and pay.', open: 'Hi, welcome! Here are the menus. Can I get you something to drink?' },
{ id: 'taxi', p: 2, t: 'Taxi small talk', role: 'A chatty London taxi driver who loves football and asks where the learner is from and what they do.', goal: 'Keep the conversation going for the whole ride.', open: "Evening! Where are we off to? You're not from around here, are you?" },
{ id: 'nego', p: 2, t: 'Price negotiation', role: 'A tough buyer for a chain of shops. Wants 30% off the price of the learner’s app, pushes back twice, and agrees only to a fair compromise.', goal: 'Defend your price and find a deal both sides like.', open: "Look, I like your product, but your price is too high for us. Can you do thirty percent off?" },
{ id: 'angry', p: 2, t: 'Angry customer', role: 'A shop manager whose bills went to the wrong customers. Angry at first, calms down if the learner apologises clearly and gives a plan.', goal: 'Calm the customer: apologise, explain and give a solution.', open: "I'm very unhappy. Your app sent our bills to the wrong customers. What happened?" },
{ id: 'skeptic', p: 2, t: 'Explain AI to a skeptic', role: 'An uncle who thinks AI is dangerous and will take all jobs. Asks simple but tough questions.', goal: 'Explain AI simply and give your opinion.', open: "Everybody talks about this AI thing. Honestly, I think it's dangerous. Why do you use it?" },
{ id: 'investor', p: 3, t: 'Investor meeting', role: 'An investor in London. Asks tough questions: market size, competition, why this team, how money will be used.', goal: 'Convince the investor with clear, structured answers.', open: "Thanks for coming in. You have ten minutes. Why should I invest in your company?" },
{ id: 'podcast', p: 3, t: 'Podcast interview', role: 'The host of a tech podcast interviewing the learner about their journey, their app and their advice for young founders in Africa.', goal: 'Tell your story with details and examples.', open: "Welcome to the show! Let's start at the beginning: how did you get into tech?" },
{ id: 'support', p: 3, t: 'Support call', role: 'A customer support agent of a cloud company. The learner’s account is blocked. Asks for details and gives steps.', goal: 'Explain your problem clearly and get it fixed.', open: "Thanks for calling CloudBase support, this is Mia. How can I help you today?" },
{ id: 'plans', p: 3, t: 'Planning a visit', role: 'Lucia, a Brazilian founder friend who wants to visit the learner’s city next month. Asks what to see, eat and do.', goal: 'Plan the visit: dates, places, food, activities.', open: "Hey! So I'm finally coming next month. What should we do?" }
];

